mapper.select:
select f.*, b.org_id as permission_org_id, b.create_by as permission_create_by from ai_knowledge_folder f join ai_knowledge_base b on b.id = f.knowledge_base_id and b.del_flag = 0 where f.del_flag = 0 and f.knowledge_base_id = #{knowledgeBaseId}
and f.data_status = #{dataStatus}
order by f.sort_order, f.id
